package com.reqlens.app;
import android.app.*;import android.os.Bundle;import android.widget.*;
public final class SettingsActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,20,20,20);TextView t=new TextView(this);t.setText("Settings");t.setTextSize(24);r.addView(t);CheckBox js=new CheckBox(this);js.setText("Browser JavaScript");js.setChecked(SuiteSettings.javascript(this));js.setOnCheckedChangeListener((x,v)->SuiteSettings.javascript(this,v));r.addView(js);CheckBox ua=new CheckBox(this);ua.setText("Desktop browser User-Agent");ua.setChecked(SuiteSettings.desktopUa(this));ua.setOnCheckedChangeListener((x,v)->SuiteSettings.desktopUa(this,v));r.addView(ua);CheckBox inc=new CheckBox(this);inc.setText("Incognito browser session");inc.setChecked(SuiteSettings.incognito(this));inc.setOnCheckedChangeListener((x,v)->SuiteSettings.incognito(this,v));r.addView(inc);CheckBox red=new CheckBox(this);red.setText("Redact sensitive values by default");red.setChecked(SuiteSettings.redact(this));red.setOnCheckedChangeListener((x,v)->SuiteSettings.redact(this,v));r.addView(red);EditText days=new EditText(this);days.setInputType(2);days.setHint("Retention days (1-90)");days.setText(String.valueOf(SuiteSettings.retentionDays(this)));r.addView(days);Button save=new Button(this);save.setText("SAVE RETENTION");save.setOnClickListener(v->{try{SuiteSettings.retentionDays(this,Integer.parseInt(days.getText().toString()));Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Enter 1-90",Toast.LENGTH_SHORT).show();}});r.addView(save);TextView note=new TextView(this);note.setText("ReqLens keeps standard Android TLS validation and does not bypass certificate pinning, mTLS or anti-debug protections.");r.addView(note);setContentView(r);}
}
